theorem wordBoundary_conj (x : Fin n → G) (u : FreeGroup (Fin n)) {r : FreeGroup (Fin n)}
    (hr : FreeGroup.lift x r = 1) :
    wordBoundary x (u * r * u⁻¹) = MonoidAlgebra.of ℤ G (FreeGroup.lift x u) • wordBoundary x r

theorem transportLin_apply (e : G ≃* H) {c c' : ℕ}
    (d : FreeMod G c →ₗ[MonoidAlgebra ℤ G] FreeMod G c') (w : FreeMod H c) :
    transportLin e d w = freeTransport e c' (d ((freeTransport e c).symm w))

theorem filter_eq_nil_of_adj (hG : IsGraph adj) {B : List (Letter N)} {s a b : Fin N}
    (hc : InCol adj s a b) (hB : ∀ y ∈ B, adj s y.1) :
    B.filter (fun y => decide (y.1 = a ∨ y.1 = b)) = []

theorem not_canPop_after_pop (hG : IsGraph adj) {x : Letter N} {B A : List (Letter N)}
    (hB : ∀ y ∈ B, adj x.1 y.1) (hw : Reduced adj (B ++ x.inv :: A)) :
    ¬ CanPop adj x.inv (proj adj (B ++ A))

theorem rest_of_mem_closure (hG : IsGraph adj) {K : Finset (Fin N)} {g : Equiv.Perm (Pos adj)}
    (hg : g ∈ Subgroup.closure (gen hG '' (K : Set (Fin N)))) (p : Pos adj) :
    rest K (g p).1 = rest K p.1

theorem diagramGroup.ι_eq_one_of_mem {x : Monoid.CoprodI fun _ : Fin r => G}
    (hx : x ∈ relators r T G) :
    (QuotientGroup.mk' (Subgroup.normalClosure (relators r T G)) x : diagramGroup r T G) = 1

theorem swap_mul_pow_add_apply (hab : ¬ π.SameCycle a b) {j : ℕ}
    (hj : j < minimalPeriod π b) :
    ((swap a b * π) ^ (minimalPeriod π a + j)) a = (π ^ j) b

theorem eqvGen_pairStep_swap_mul (p₀ q : Perm D) (x y : D) {u v : D}
    (h : Relation.EqvGen (pairStep (swap x y * p₀) q) u v) :
    Relation.EqvGen (joinRel (pairStep p₀ q) x y) u v

theorem NPC.eq_one_of_φ_mul_φ_eq_one (hC : C.NPC) {v v' : V} {t : T} (h : C.inc v t)
    (h' : C.inc v' t) (hne : v ≠ v') {a : C.A v} {a' : C.A v'}
    (ha : C.φ v t h a * C.φ v' t h' a' = 1) : a = 1 ∧ a' = 1
